// Guarda de ritmo: bloqueia chamadas com menos de 2s de intervalo.
// Protege contra loop no Electron disparando centenas de ações reais.
const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const last = staticData.lastCall || 0;
const incoming = $input.first().json.body || $input.first().json || {};
if (now - last < 2000) {
  return [{ json: { blocked: true, reason: 'rate-limit' } }];
}
staticData.lastCall = now;
return [{ json: {
  blocked: false,
  userId: incoming.userId || 'tony-stark',
  message: incoming.message || '',
  sessionId: incoming.sessionId || 'default'
} }];
